#include "Core/HelpyDeliveryFlags.h"
#include <cassert>
#include <chrono>
#include <fstream>
// Helpy delivery flags: signature checks, newest-seq rule, key pinning, the player's own
// opt-out and per-mod choices, and the limits on what a flags folder can do.
namespace {
namespace fs=std::filesystem;using namespace PS::HelpyDeliveryFlags;
struct Row{std::string Statement,Sig;};
// Generated by a one-off script with fixed private scalars; regenerate rather than hand-edit.
const std::string KeyA="3059301306072a8648ce3d020106082a8648ce3d030107034200048c4a837cb567e4883fcc518ed4e9229caea10c8ede6d0830f8a978ba86f706247bd3cddb04fd341f290fb488480f8459982b86298d1914cb99584004446a50e6",KeyB="3059301306072a8648ce3d020106082a8648ce3d03010703420004f77f4c3c67be0834c8ba25d24157c68da61cb9aa1c4b634ceef8af33bf5063ad9923b66992f3f1aeb020dfe4376c9b0573779ed6caa2fc627d73c955fed2a7bb";
const Row charOn{"helpy-flag/1\n{\"mod\":\"grandexchange\",\"target\":\"character\",\"id\":\"5A3F0C21B6D84E7F9A1C2B3D4E5F6071\",\"flag\":\"noPlayerDeliveries\",\"on\":true,\"seq\":3,\"at\":1800000000,\"message\":\"This character trades on the Grand Exchange.\"}","3045022100c82c04725ce20eb0102bfa278d6914a8fdf0743c488cea7564989fede5507222022027f0c4e3fd367ead64d8ae4d84c0887bee9fd2567de7bf10722863e036d52e83"};
const Row charOldOff{"helpy-flag/1\n{\"mod\":\"grandexchange\",\"target\":\"character\",\"id\":\"5A3F0C21B6D84E7F9A1C2B3D4E5F6071\",\"flag\":\"noPlayerDeliveries\",\"on\":false,\"seq\":2,\"at\":1800000000}","3046022100de715da0f2be7d3eaca4d3d43d04a0516615f4e6f4b2649e1bd782d8a0d31c20022100d406893a19105c598d905fab8c24ecebe4ad8a9c1eb0664457adbcb03f3dda32"};
const Row worldOn{"helpy-flag/1\n{\"mod\":\"grandexchange\",\"target\":\"world\",\"id\":\"00112233445566778899AABBCCDDEEFF\",\"flag\":\"noPlayerDeliveries\",\"on\":true,\"seq\":1,\"at\":1800000000}","3044022071c0c1ed03279336e0ab4efd5d7388afe43676c668afb5508b2b0cc5bae7090702205138775a627405bf0172b752d85295f9fb43f5099e5f661aa5dd2776708d9a92"};
const Row otherOn{"helpy-flag/1\n{\"mod\":\"grandexchange\",\"target\":\"character\",\"id\":\"ABCDEFABCDEFABCDEFABCDEFABCDEF01\",\"flag\":\"noPlayerDeliveries\",\"on\":true,\"seq\":1,\"at\":1800000000}","304402202f2c8469cbf2e9b71116f2227aa0a00b1967315200a9d5922cc5fb44dd64c8ad02202cd1b99a10c2a97ef575bb680b4cfa9208ea2bd8a96b4c2ea488cdcf72469538"};
const Row otherOff{"helpy-flag/1\n{\"mod\":\"grandexchange\",\"target\":\"character\",\"id\":\"ABCDEFABCDEFABCDEFABCDEFABCDEF01\",\"flag\":\"noPlayerDeliveries\",\"on\":false,\"seq\":2,\"at\":1800000000}","3045022100cbae98bb55ea330d84c231552cce93ad15a1d89f80d1af614d24474ef90051ba02204e79d6598c0b1a37909017032b9a9762c25705938ba9329d7f09d399d506e3a3"};
const Row wrongMod{"helpy-flag/1\n{\"mod\":\"othermod\",\"target\":\"character\",\"id\":\"ABCDEFABCDEFABCDEFABCDEFABCDEF01\",\"flag\":\"noPlayerDeliveries\",\"on\":true,\"seq\":9,\"at\":1800000000}","304502200ad9470f3fdddd3aed6e6a6604ba1e95ebe23872e34d5cd67b799e21c48f4b6b02210082e30d154222c2c89a950c0cbe12cc0053125b14dc931557451e93afcf48ed5e"};
const Row signedByB{"helpy-flag/1\n{\"mod\":\"grandexchange\",\"target\":\"character\",\"id\":\"ABCDEFABCDEFABCDEFABCDEFABCDEF01\",\"flag\":\"noPlayerDeliveries\",\"on\":true,\"seq\":9,\"at\":1800000000}","3045022100aeeeb9df20eed66e1c7cb0e8712ec7610d5310ca1b5380f3b341625d6969b50e022016bd77d1394662fe825810953ad7681ae5e7d1b5e5402a887cfedd86c4b0fa90"};
const std::string C="5A3F0C21B6D84E7F9A1C2B3D4E5F6071",W="00112233445566778899AABBCCDDEEFF",D="ABCDEFABCDEFABCDEFABCDEFABCDEF01";
void Put(const fs::path& path,const std::string& text){fs::create_directories(path.parent_path());std::ofstream(path,std::ios::binary)<<text;}
void Register(const fs::path& folder,const std::string& id,const std::string& key){Put(folder/id/"mod.json",Json{{"id",id},{"name","Grand Exchange"},{"publicKey",key}}.dump());}
void Flags(const fs::path& folder,const std::string& id,const std::vector<Row>& rows){
    Json flags=Json::array();for(const auto& row:rows)flags.push_back({{"statement",row.Statement},{"sig",row.Sig}});
    Put(folder/id/"flags.json",Json{{"flags",flags}}.dump());
}
Snapshot Now(const fs::path& folder){return Read(folder,Signature::DefaultVerifier(),1800000100);}
}
int main(){
    const auto root=fs::temp_directory_path()/("helpy-delivery-flags-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));
    const auto folder=root/"flags";
    // Signature primitives: exact SPKI form, strict DER, and real verification.
    {const auto key=Signature::FromHex(KeyA);assert(Signature::P256Point(key).has_value());
        assert(!Signature::P256Point(Signature::FromHex(KeyA.substr(0,KeyA.size()-2))));
        assert(Signature::Fingerprint(key).starts_with("sha256:")&&Signature::Fingerprint(key).size()==71);
        assert(Signature::Verify(key,charOn.Statement,Signature::FromHex(charOn.Sig)));
        assert(!Signature::Verify(key,charOn.Statement+" ",Signature::FromHex(charOn.Sig)));
        assert(!Signature::Verify(Signature::FromHex(KeyB),charOn.Statement,Signature::FromHex(charOn.Sig)));
        auto padded=Signature::FromHex(charOn.Sig);padded.push_back(0);assert(!Signature::RawSignature(padded));
        Signature::Bytes nonMinimal{0x30,0x08,0x02,0x02,0x00,0x01,0x02,0x02,0x00,0x01};assert(!Signature::RawSignature(nonMinimal));
        Signature::Bytes negative{0x30,0x06,0x02,0x01,0x81,0x02,0x01,0x01};assert(!Signature::RawSignature(negative));
        bool threw=false;try{(void)Signature::FromHex("abc");}catch(...){threw=true;}assert(threw);}
    // Statements: exact prefix, one line, matching mod, valid target and GUID.
    assert(ParseStatement(charOn.Statement,"grandexchange").has_value()&&!ParseStatement(charOn.Statement,"othermod"));
    assert(!ParseStatement(charOn.Statement.substr(1),"grandexchange")&&!ParseStatement(charOn.Statement+"\n","grandexchange"));
    assert(NormalizeGuid("{5a3f0c21-b6d8-4e7f-9a1c-2b3d4e5f6071}")==C&&NormalizeGuid(std::string(32,'0')).empty()&&NormalizeGuid("xyz").empty());
    // No folder: nothing blocks.
    {const auto snapshot=Now(folder);assert(snapshot.Mods.empty()&&!Check(snapshot,C,W));}
    // A signed pause blocks the character; the older "off" does not lift it; the world flag blocks every character in that world.
    Register(folder,"grandexchange",KeyA);Flags(folder,"grandexchange",{charOn,charOldOff,worldOn,otherOn,otherOff,wrongMod,signedByB});
    {const auto snapshot=Now(folder);assert(snapshot.Mods.size()==1&&snapshot.Mods[0].Key==ModStatus::Trust::FirstSeen);
        assert(snapshot.Mods[0].Valid==5&&snapshot.Mods[0].Rejected==2); // wrongMod names another mod; signedByB fails the key.
        const auto block=Check(snapshot,C,"");assert(block&&!block->User&&block->Mod=="grandexchange"&&block->Message=="This character trades on the Grand Exchange.");
        assert(!Check(snapshot,D,"")); // seq 2 "off" lifted seq 1 "on".
        const auto world=Check(snapshot,D,W);assert(world&&world->Target=="world"&&world->Message=="Grand Exchange has paused Helpy deliveries to this world.");
        assert(AnyCharacterPause(snapshot));}
    // The first key seen is pinned; a replaced mod.json key is refused until the player resets it.
    {const auto state=ReadState(folder);assert(state["mods"]["grandexchange"]["fingerprint"]==Signature::Fingerprint(Signature::FromHex(KeyA)));
        Register(folder,"grandexchange",KeyB);const auto swapped=Now(folder);
        assert(swapped.Mods[0].Key==ModStatus::Trust::Mismatch&&swapped.Active.empty());
        // Every flag from a distrusted mod is ignored until the player resets its key.
        ResetKey(folder,"grandexchange",1800000200);const auto reset=Now(folder);assert(reset.Mods[0].Key==ModStatus::Trust::FirstSeen);
        assert(!Check(reset,C,"")); // Real flags fail against the new key: lifting requires the player's recorded reset.
        const auto events=ReadState(folder)["events"];assert(events.size()>=3&&events[events.size()-2]["event"]=="key-reset");
        ResetKey(folder,"grandexchange",1800000300);Register(folder,"grandexchange",KeyA);assert(Check(Now(folder),C,""));}
    // The player's choice per mod is honoured and recorded for the mod to read.
    {SetModAllowed(folder,"grandexchange",false,1800000400);const auto declined=Now(folder);
        assert(!Check(declined,C,W)&&declined.Declined.size()==2&&ReadState(folder)["mods"]["grandexchange"]["allowPause"]==false);
        SetModAllowed(folder,"grandexchange",true,1800000500);assert(Check(Now(folder),C,""));}
    // The player's own opt-out for a character, with no mod involved.
    {SetUserDeliveries(folder,D,false,1800000600,"Alt");auto snapshot=Now(folder);const auto block=Check(snapshot,"{abcdefab-cdef-abcd-efab-cdefabcdef01}","");
        assert(block&&block->User&&!UserAllows(snapshot.State,D));
        SetUserDeliveries(folder,D,true,1800000700);assert(!Check(Now(folder),D,""));
        bool threw=false;try{SetUserDeliveries(folder,"bad",false,0);}catch(...){threw=true;}assert(threw);}
    // Folder hygiene: invalid ids, mismatched registrations, broken files and the mod limit.
    {Register(folder,"Bad Name",KeyA);Put(folder/"other"/"mod.json",Json{{"id","different"},{"publicKey",KeyA}}.dump());
        Register(folder,"broken",KeyA);Put(folder/"broken"/"flags.json","{not json");
        const auto snapshot=Now(folder);int problems=0;for(const auto& mod:snapshot.Mods)if(!mod.Problem.empty())++problems;
        assert(problems==3&&Check(snapshot,C,"")); // The good mod still applies.
        assert(!ReadState(folder)["mods"].contains("Bad Name"));}
    {Put(folder/"helpy-state.json","garbage");const auto snapshot=Now(folder);assert(snapshot.State["version"]==1);}
    {const auto crowded=root/"crowded";for(int i=0;i<70;++i)Register(crowded,"mod"+std::to_string(100+i),KeyA);
        const auto snapshot=Read(crowded,Signature::DefaultVerifier(),0,false);assert(snapshot.Mods.size()==MaxMods&&!snapshot.Problems.empty());
        assert(!fs::exists(crowded/"helpy-state.json"));} // record=false never writes.
    std::error_code error;fs::remove_all(root,error);
}
